        .struct_ => |_ptr_s| {
            const s = _ptr_s.*;
// zbr:selfhost/TypeChecker.zbr:4556
            for (s.members.items) |smem| {
// zbr:selfhost/TypeChecker.zbr:4557
                _zbr_fn_checkHatClassDecl(smem, file, ctx);
